from AlgorithmImport import *

class QuantConnectAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol

        self.spy_sma = SimpleMovingAverage(20)
        self.aapl_rsi = RelativeStrengthIndex(14)

        self.strategy_a_holdings = 0
        self.strategy_b_holdings = 0

        self.spy_prev_close = None
        self.spy_prev_sma = None
        self.aapl_consecutive_red = 0
        self.aapl_prev_close = None
        self.indicators_ready = False

    def OnData(self, data):
        for ticker in self.tickers:
            if self.symbols[ticker] not in data:
                return

        spy_close = data[self.symbols["SPY"]].Close
        aapl_close = data[self.symbols["AAPL"]].Close

        self.spy_sma.Update(self.Time, spy_close)
        self.aapl_rsi.Update(self.Time, aapl_close)

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        if not self.indicators_ready:
            self.indicators_ready = True
            self.spy_prev_close = spy_close
            self.spy_prev_sma = self.spy_sma.Current.Value
            self.aapl_prev_close = aapl_close
            return

        if aapl_close < self.aapl_prev_close:
            self.aapl_consecutive_red += 1
        else:
            self.aapl_consecutive_red = 0

        if self.strategy_a_holdings > 0:
            spy_crossed_below = (self.spy_prev_close >= self.spy_prev_sma) and (spy_close < self.spy_sma.Current.Value)
            if spy_crossed_below:
                self.Liquidate(self.symbols["SPY"])
                self.strategy_a_holdings = 0

        if self.strategy_b_holdings > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.Liquidate(self.symbols["AAPL"])
                self.strategy_b_holdings = 0

        if self.strategy_a_holdings == 0:
            spy_crossed_above = (self.spy_prev_close <= self.spy_prev_sma) and (spy_close > self.spy_sma.Current.Value)
            if spy_crossed_above:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                qty = int(portfolio_value * 0.4 / spy_close)
                if qty > 0:
                    self.Buy(self.symbols["SPY"], qty)
                    self.strategy_a_holdings = qty

        if self.strategy_b_holdings == 0:
            if self.aapl_consecutive_red >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    qty = int(20000 / aapl_close)
                    if qty > 0:
                        self.Buy(self.symbols["AAPL"], qty)
                        self.strategy_b_holdings = qty

        self.spy_prev_close = spy_close
        self.spy_prev_sma = self.spy_sma.Current.Value
        self.aapl_prev_close = aapl_close

