        self.RegisterIndicator("SPY", self.spy_sma, Resolution.Daily)
        self.RegisterIndicator("AAPL", self.aapl_rsi, Resolution.Daily)

        self.last_spy_close = None
        self.last_sma_value = None
        self.last_aapl_close = None

    def OnData(self, data):
        for symbol in self.symbols:
            if not data.ContainsKey(symbol):
                return

        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            self.last_spy_close = spy_close
            self.last_aapl_close = aapl_close
            return

        current_sma = self.spy_sma.Current.Value
        current_rsi = self.aapl_rsi.Current.Value

        if self.last_aapl_close is not None:
            if aapl_close < self.last_aapl_close:
                self.aapl_consecutive_red += 1
            else:
                self.aapl_consecutive_red = 0

        spy_quantity = self.Portfolio["SPY"].Quantity
        aapl_quantity = self.Portfolio["AAPL"].Quantity

        if spy_quantity > 0 and self.last_spy_close is not None and self.last_sma_value is not None:
            if self.last_spy_close >= self.last_sma_value and spy_close < current_sma:
                self.Liquidate("SPY")

        if aapl_quantity > 0:
            if current_rsi > 60:
                self.Liquidate("AAPL")

        if spy_quantity == 0 and self.last_spy_close is not None and self.last_sma_value is not None:
            if self.last_spy_close <= self.last_sma_value and spy_close > current_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.4
                shares = int(target_value / spy_close)
                if shares > 0:
                    self.Buy("SPY", shares)

        if aapl_quantity == 0 and self.aapl_consecutive_red >= 3:
            available_cash = self.Portfolio.Cash
            if available_cash >= 20000:
                shares = int(20000 / aapl_close)
                if shares > 0:
                    self.Buy("AAPL", shares)

        self.last_spy_close = spy_close
        self.last_sma_value = current_sma
        self.last_aapl_close = aapl_close

