class QuantConnectAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for ticker in self.tickers:
            self.AddEquity(ticker, Resolution.Daily)

        self.spy_sma = self.SMA("SPY", 50)
        self.spy_prev_close = None
        self.spy_prev_sma = None

        self.aapl_rsi = self.RSI("AAPL", 14)
        self.aapl_prev_close = None
        self.aapl_red_days = 0

    def OnData(self, data):
        for ticker in self.tickers:
            if ticker not in data or data[ticker] is None:
                return

        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close

        if self.spy_sma.IsReady:
            sma_value = self.spy_sma.Current.Value

            if self.spy_prev_close is None:
                self.spy_prev_close = spy_close
                self.spy_prev_sma = sma_value
            else:
                spy_holdings = self.Portfolio["SPY"].Quantity

                if spy_holdings > 0:
                    if self.spy_prev_close >= self.spy_prev_sma and spy_close < sma_value:
                        self.MarketOrder("SPY", -spy_holdings)

                spy_holdings = self.Portfolio["SPY"].Quantity

                if spy_holdings == 0:
                    if self.spy_prev_close <= self.spy_prev_sma and spy_close > sma_value:
                        portfolio_value = self.Portfolio.TotalPortfolioValue
                        invest_amount = portfolio_value * 0.40
                        shares_to_buy = int(invest_amount / spy_close)
                        if shares_to_buy > 0:
