from AlgorithmImports import *

class QuantConnectAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = self.SMA(self.symbols["SPY"], 50)
        self.AddIndicator(self.symbols["SPY"], self.spy_sma)

        self.aapl_rsi = self.RSI(self.symbols["AAPL"], 14)
        self.AddIndicator(self.symbols["AAPL"], self.aapl_rsi)

        self.close_prices = {ticker: None for ticker in self.symbols}
        self.prev_close_prices = {ticker: None for ticker in self.symbols}
        self.prev_spy_sma = None

        self.aapl_red_days = 0

    def OnData(self, data):
        for ticker in self.symbols:
            if not data.ContainsKey(self.symbols[ticker]):
                return

        for ticker in self.symbols:
            symbol = self.symbols[ticker]
            self.prev_close_prices[ticker] = self.close_prices[ticker]
            self.close_prices[ticker] = data[symbol].Close

        if self.prev_close_prices["AAPL"] is not None:
            if self.close_prices["AAPL"] < self.prev_close_prices["AAPL"]:
                self.aapl_red_days += 1
            else:
                self.aapl_red_days = 0

        spy_symbol = self.symbols["SPY"]
        aapl_symbol = self.symbols["AAPL"]

        if self.spy_sma.IsReady:
            spy_holdings = self.Portfolio[spy_symbol].Quantity

            if spy_holdings > 0:
                if (self.prev_close_prices["SPY"] is not None and self.prev_spy_sma is not None and
                    self.prev_close_prices["SPY"] >= self.prev_spy_sma and
                    self.close_prices["SPY"] < self.spy_sma.Current.Value):
                    self.Liquidate(spy_symbol)

            if spy_holdings == 0:
                if (self.prev_close_prices["SPY"] is not None and self.prev_spy_sma is not None and
                    self.prev_close_prices["SPY"] <= self.prev_spy_sma and
                    self.close_prices["SPY"] > self.spy_sma.Current.Value):
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    amount_to_invest = portfolio_value * 0.4
                    shares_to_buy = int(amount_to_invest / self.close_prices["SPY"])
                    if shares_to_buy > 0:
                        self.Buy(spy_symbol, shares_to_buy)

            self.prev_spy_sma = self.spy_sma.Current.Value

        if self.aapl_rsi.IsReady:
            aapl_holdings = self.Portfolio[aapl_symbol].Quantity

            if aapl_holdings > 0:
                if self.aapl_rsi.Current.Value > 60:
                    self.Liquidate(aapl_symbol)

            if aapl_holdings == 0:
                if self.aapl_red_days >= 3:
                    available_cash = self.Portfolio.Cash
                    if available_cash >= 20000:
                        shares_to_buy = int(20000 / self.close_prices["AAPL"])
                        if shares_to_buy > 0:
                            self.Buy(aapl_symbol, shares_to_buy)

