            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol

        self.ma_period = 20
        self.spy_closes = []

        self.rsi_period = 14
        self.aapl_closes = []

        self.aapl_red_streak = 0
        self.aapl_prev_close = None

    def OnData(self, data):
        if not all(self.symbols[ticker] in data for ticker in self.tickers):
            return

        spy_close = data[self.symbols["SPY"]].Close
        aapl_close = data[self.symbols["AAPL"]].Close

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        if len(self.spy_closes) < self.ma_period + 1 or len(self.aapl_closes) < self.rsi_period + 1:
            return

        if len(self.spy_closes) > self.ma_period + 10:
            self.spy_closes.pop(0)
        if len(self.aapl_closes) > self.rsi_period + 10:
            self.aapl_closes.pop(0)

        spy_ma = sum(self.spy_closes[-self.ma_period:]) / self.ma_period
        prev_ma = sum(self.spy_closes[-self.ma_period-1:-1]) / self.ma_period
        prev_close = self.spy_closes[-2]

        aapl_rsi = self.calculate_rsi(self.aapl_closes, self.rsi_period)

        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
        self.aapl_prev_close = aapl_close

        spy_holdings = self.Portfolio[self.symbols["SPY"]].Quantity
        aapl_holdings = self.Portfolio[self.symbols["AAPL"]].Quantity

        if spy_holdings > 0:
            if prev_close > prev_ma and spy_close <= spy_ma:
                self.Liquidate(self.symbols["SPY"])

        if aapl_holdings > 0:
            if aapl_rsi > 60:
                self.Liquidate(self.symbols["AAPL"])

        if spy_holdings == 0:
            if prev_close <= prev_ma and spy_close > spy_ma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.4
                qty = int(invest_amount / spy_close)
                if qty > 0:
                    self.Buy(self.symbols["SPY"], qty)

        if aapl_holdings == 0:
            if self.aapl_red_streak >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    qty = int(20000 / aapl_close)
                    if qty > 0:
                        self.Buy(self.symbols["AAPL"], qty)

    def calculate_rsi(self, prices, period):
        if len(prices) < period + 1:
            return 50

        recent = prices[-(period+1):]
        gains = 0.0
        losses = 0.0
        for i in range(1, len(recent)):
            change = recent[i] - recent[i-1]
            if change > 0:
                gains += change
            else:
                losses += -change

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100.0 if avg_gain > 0 else 50.0

        rs = avg_gain / avg_loss
        rsi = 100.0 - (100.0 / (1.0 + rs))
        return rsi

