        self.spy_sma_100 = self.SMA(self.symbols["SPY"], 100, Resolution.Daily)
        self.spy_prev_close = None
        self.spy_prev_sma = None

        # Strategy B (AAPL) - Red days and RSI
        self.aapl_lot = 0
        self.aapl_closes = []
        self.aapl_rsi = self.RSI(self.symbols["AAPL"], 14, Resolution.Daily)

        # Warmup for 100 days to ensure indicators are ready
        self.SetWarmupPeriod(100)

    def OnData(self, data):
        # Skip if any required ticker is missing
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            if self.symbols[ticker] not in data:
                return

        spy_close = data[self.symbols["SPY"]].Close
        aapl_close = data[self.symbols["AAPL"]].Close

        # === STRATEGY A: SPY SMA Crossover ===
        if self.spy_sma_100.IsReady:
            spy_sma = self.spy_sma_100.Current.Value

            # Evaluate sell first
            if self.spy_lot > 0:
                if self.spy_prev_close is not None and self.spy_prev_sma is not None:
                    # Sell: SPY crosses below SMA
                    if self.spy_prev_close >= self.spy_prev_sma and spy_close < spy_sma:
                        self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                        self.spy_lot = 0

            # Evaluate buy
            if self.spy_lot == 0:
                if self.spy_prev_close is not None and self.spy_prev_sma is not None:
                    # Buy: SPY crosses above SMA
                    if self.spy_prev_close <= self.spy_prev_sma and spy_close > spy_sma:
                        portfolio_value = self.Portfolio.TotalPortfolioValue
                        target_value = portfolio_value * 0.40
                        shares = int(target_value / spy_close)
                        if shares > 0:
                            self.MarketOrder(self.symbols["SPY"], shares)
