        if len(self.aapl_closes) > 100:
            self.aapl_closes.pop(0)

        # Evaluate sell first
        if self.aapl_lot > 0:
            if self.aapl_rsi.IsReady:
                aapl_rsi = self.aapl_rsi.Current.Value
                # Sell: RSI > 60
                if aapl_rsi > 60:
                    self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                    self.aapl_lot = 0

        # Evaluate buy
        if self.aapl_lot == 0 and len(self.aapl_closes) >= 4:
            # Buy: AAPL red for 3 consecutive days
            consecutive_red = 0
            for i in range(len(self.aapl_closes) - 1, 0, -1):
                if self.aapl_closes[i] < self.aapl_closes[i-1]:
                    consecutive_red += 1
                else:
                    break

            if consecutive_red >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.symbols["AAPL"], shares)
                        self.aapl_lot = shares

