    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        self.symbols["SPY"] = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.symbols["AAPL"] = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.symbols["IBM"] = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.symbols["BAC"] = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.symbols["AIG"] = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_closes = []
        self.spy_last_close = None
        self.spy_last_sma = None

        self.aapl_closes = []
        self.aapl_last_close = None
        self.aapl_red_days = 0

    def OnData(self, data):
        required_tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for ticker in required_tickers:
            if not data.ContainsKey(self.symbols[ticker]):
                return

        spy_close = data[self.symbols["SPY"]].Close
        aapl_close = data[self.symbols["AAPL"]].Close

        self.spy_closes.append(spy_close)
        if len(self.spy_closes) > 100:
            self.spy_closes.pop(0)

        self.aapl_closes.append(aapl_close)
        if len(self.aapl_closes) > 14:
            self.aapl_closes.pop(0)

        if self.aapl_last_close is not None:
            if aapl_close < self.aapl_last_close:
                self.aapl_red_days += 1
            else:
                self.aapl_red_days = 0

        current_spy_sma = sum(self.spy_closes) / len(self.spy_closes) if len(self.spy_closes) == 100 else None

        if len(self.spy_closes) < 100 or len(self.aapl_closes) < 14:
            self.spy_last_sma = current_spy_sma
            self.spy_last_close = spy_close
            self.aapl_last_close = aapl_close
            return

        self.EvaluateSells(spy_close, aapl_close, current_spy_sma)
        self.EvaluateBuys(spy_close, aapl_close, current_spy_sma)

        self.spy_last_sma = current_spy_sma
        self.spy_last_close = spy_close
        self.aapl_last_close = aapl_close

    def EvaluateSells(self, spy_close, aapl_close, current_spy_sma):
        spy_lot = self.Portfolio[self.symbols["SPY"]].Quantity
        if spy_lot > 0:
            if self.spy_last_sma is not None and self.spy_last_close is not None:
                if self.spy_last_close >= self.spy_last_sma and spy_close < current_spy_sma:
                    self.MarketOrder(self.symbols["SPY"], -spy_lot)

        aapl_lot = self.Portfolio[self.symbols["AAPL"]].Quantity
        if aapl_lot > 0:
            rsi = self.CalculateRSI(self.aapl_closes)
            if rsi > 60:
                self.MarketOrder(self.symbols["AAPL"], -aapl_lot)

    def EvaluateBuys(self, spy_close, aapl_close, current_spy_sma):
        spy_lot = self.Portfolio[self.symbols["SPY"]].Quantity
        if spy_lot == 0:
            if self.spy_last_sma is not None and self.spy_last_close is not None:
                if self.spy_last_close <= self.spy_last_sma and spy_close > current_spy_sma:
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    invest_amount = portfolio_value * 0.4
                    shares = int(invest_amount / spy_close)
                    if shares > 0:
                        self.MarketOrder(self.symbols["SPY"], shares)

        aapl_lot = self.Portfolio[self.symbols["AAPL"]].Quantity
        if aapl_lot == 0:
            if self.aapl_red_days >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.symbols["AAPL"], shares)

    def CalculateRSI(self, closes):
        if len(closes) < 14:
            return 50.0

        prices = closes[-14:]
        gains = 0.0
        losses = 0.0

        for i in range(1, 14):
            change = prices[i] - prices[i-1]
            if change > 0:
                gains += change
            else:
                losses += abs(change)

        avg_gain = gains / 14.0
        avg_loss = losses / 14.0

        if avg_loss == 0:
            return 100.0

        rs = avg_gain / avg_loss
        rsi = 100.0 - (100.0 / (1.0 + rs))

        return rsi

